  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
}
.b { transition: transform var(--dur-base) var(--ease-enter); }
@media (prefers-reduced-motion: reduce) { :root { --dur-base: 140ms; } }

.f { transition: width var(--dur-base) var(--ease-move); }
@keyframes grow {
  from { height: 0; }
  to { height: 40px; }
}
